JavaScript:
/*:
 * Prevent Assist Main Party
 *
 * @plugindesc v1.0.0 This plugin prevent Assist to be in Main Party.
 * @author Vyndicate
 *
 *
 * @help
 * There is no Plugin Command for this plugin.
 *
 * ============================================================================
 * Prevent actor to change
 *
 * Reference from Plugin Zero_G
 *
 * ============================================================================
 */

(function () {
    var popupMessage;
    var _Scene_Base_start = Scene_Base.prototype.start;
    Scene_Base.prototype.start = function () {
        _Scene_Base_start.call(this);

        popupMessage = new Sprite(new Bitmap(Graphics.width, Graphics.height));
        popupMessage.opacity = 255;
        this.addChild(popupMessage);
    };

    SceneManager.showMessagePreventChange = function () {
        popupMessage.bitmap.clear();
        popupMessage.opacity = 255;

        popupMessage.bitmap.drawText("Assist hero cannot be in Main Party!", 0, Graphics.height / 2, Graphics.width, 30, 'center');
    };

    var _Scene_Base_update = Scene_Base.prototype.update;
    Scene_Base.prototype.update = function () {
        _Scene_Base_update.call(this);

        if (typeof popupMessage !== 'undefined') {
            if (popupMessage.opacity > 0) {
                popupMessage.opacity -= 3;
            }
        }
    }

    var _Swapping_Actor = Scene_Menu.prototype.onFormationOk
    Scene_Menu.prototype.onFormationOk = function() {
        var index = this._statusWindow.index();
        var actor = $gameParty.members()[index];
        var pendingIndex = this._statusWindow.pendingIndex();
        if (pendingIndex >= 0) {
            if(!this.preventSwap(index, pendingIndex)) {
                $gameParty.swapOrder(index, pendingIndex);
                this._statusWindow.setPendingIndex(-1);
                this._statusWindow.redrawItem(index);
            }
        } else {
            this._statusWindow.setPendingIndex(index);
        }
        this._statusWindow.activate();
    };

    var _Prevent_Swap = Scene_Menu.prototype.preventSwap
    Scene_Menu.prototype.preventSwap = function(index, pendingIndex) {
        if((index < 4 || pendingIndex < 4) && ($gameParty.members()[index].currentClass().name == "Assist" || $gameParty.members()[pendingIndex].currentClass().name == "Assist")) {
            console.log("You can't use Assist in main party")
            SceneManager.showMessagePreventChange()
            return true
        }
        return false
    }
}());
